def raw_matches(m,pat):
 if not pat:return []
 matches=[]
 for p in sorted((ROOT/m/'all-raw').glob('*.json')):
  if p.name=='manifest.json' or 'quality_tool' in p.name:continue
  d=json.loads(p.read_text());text=d.get('body_utf8','') or '';mt=re.search(pat,text,re.I)
  if mt:
   matches.append({'file':str(p),'excerpt':text[max(0,mt.start()-100):mt.end()+300]})
 return matches[:6]
